/**
 * The evaluation API as its contract documents it. The types come from
 * packages/contracts/openapi/evaluation-service.openapi.yaml (`evaluation.gen.ts`,
 * regenerated by `pnpm gen:api`); the contract is checked against the service
 * on every test run (ADR-0021), so what compiles here is what the service does.
 *
 * Unlike the simulation pages (which read hand-written types held to the
 * contract by `Accepts` checks), the evaluation pages read the contract's own
 * types: there is no second description of a response to drift from the first.
 */
import * as contract from "./contract";
import type { components, operations } from "./evaluation.gen";

export type EvaluationSchemas = components["schemas"];
export type EvaluationOperation = keyof operations;

/** The query parameters an operation documents. */
export type QueryOf<Op extends EvaluationOperation> = contract.QueryOf<operations, Op>;

/** The JSON body an operation accepts. */
export type BodyOf<Op extends EvaluationOperation> = contract.BodyOf<operations, Op>;

/** The JSON body of one documented response of an operation. */
export type ResponseOf<
  Op extends EvaluationOperation,
  Status extends keyof contract.ResponsesOf<operations, Op>,
> = contract.ResponseOf<operations, Op, Status>;

/** URL query parameters from the documented ones; unset and empty values are left out. */
export function queryOf<Op extends EvaluationOperation>(params: QueryOf<Op>): URLSearchParams {
  return contract.toQuery(params);
}

type S = EvaluationSchemas;

export type EvalRun = S["EvalRun"];
export type EvalRunStatus = S["EvalRunStatus"];
export type EvalRunPage = S["EvalRunPage"];
export type EvalRunResponse = S["EvalRunResponse"];
export type EvalRunDetail = S["EvalRunDetail"];
export type EvalRunSummary = S["EvalRunSummary"];
export type EvalCaseSummary = S["EvalCaseSummary"];
export type EvalCaseDetail = S["EvalCaseDetail"];
export type Classification = S["Classification"];
export type ClassCounts = S["ClassCounts"];
export type SideSummary = S["SideSummary"];
export type SideStatus = S["SideStatus"];
export type SideTotals = S["SideTotals"];
export type Metrics = S["Metrics"];
export type MetricDelta = S["MetricDelta"];
export type CaseComparison = S["CaseComparison"];
export type ExpectationChange = S["ExpectationChange"];
export type Divergence = S["Divergence"];
export type ValueChange = S["ValueChange"];
export type TrajectoryStep = S["Step"];
export type EvalExpectationResult = S["ExpectationResult"];
export type JudgedExpectation = S["JudgedExpectation"];
export type JudgeIdentity = S["JudgeIdentity"];
export type JudgeBudget = S["JudgeBudget"];
export type HumanReview = S["HumanReview"];
export type ReviewRequest = S["ReviewRequest"];
export type ReviewResponse = S["ReviewResponse"];
export type ReviewQueuePage = S["ReviewQueuePage"];
export type ReviewQueueItem = ReviewQueuePage["items"][number];
export type Dataset = S["Dataset"];
export type DatasetListItem = S["DatasetListItem"];
export type DatasetPage = S["DatasetPage"];
export type DatasetDetail = S["DatasetDetail"];
export type DatasetCase = S["DatasetCase"];
export type DatasetCaseInput = S["DatasetCaseInput"];
export type DatasetResponse = S["DatasetResponse"];
export type Criterion = S["Criterion"];
export type Calibration = S["Calibration"];
export type CalibrationPage = S["CalibrationPage"];
export type CalibrationResponse = S["CalibrationResponse"];
export type JudgeDescription = S["JudgeDescription"];

/** Review sides as the API spells them. */
export type ReviewSide = ReviewRequest["side"];
